CREATE TABLE `home_feed_contributor_cards` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(255) NOT NULL, `contributor_name` VARCHAR(255) NOT NULL, `display_name` VARCHAR(255) NOT NULL, `role` VARCHAR(64) NULL DEFAULT NULL, `description` TEXT NULL DEFAULT NULL, `avatar_url` VARCHAR(1024) NULL DEFAULT NULL, `assistant_prompts` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL, `comic_ids_json` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL, `release_ids_json` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL, `comics_eyebrow` VARCHAR(80) NULL DEFAULT NULL, `comics_title` VARCHAR(160) NULL DEFAULT NULL, `releases_eyebrow` VARCHAR(80) NULL DEFAULT NULL, `releases_title` VARCHAR(160) NULL DEFAULT NULL, `start_time` DATETIME NOT NULL, `end_time` DATETIME NOT NULL, `is_admin_only` TINYINT NOT NULL DEFAULT 0, `display_order` SMALLINT UNSIGNED NOT NULL DEFAULT 0, `created_by_user_id` INT UNSIGNED NULL DEFAULT NULL, `create_time` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, `update_time` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_hfcc_window` (`start_time`, `end_time`), KEY `idx_hfcc_contributor` (`contributor_name`), CONSTRAINT `assistant_prompts` CHECK (JSON_VALID(`assistant_prompts`)), CONSTRAINT `comic_ids_json` CHECK (JSON_VALID(`comic_ids_json`)), CONSTRAINT `release_ids_json` CHECK (JSON_VALID(`release_ids_json`))) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_unicode_ci